     * @param weeklyShare 每周分成
     * @return 合计条数
     */
    static int totalOf(int monthlyShare, int weeklyShare) {
        return monthlyShare + weeklyShare;
    }

    public static void main(String[] args) {
        int monthlyShare = {m};
        int total = totalOf(monthlyShare, WEEKLY_SHARE);
